def equi(i, y, l):
	c = 0
	if i == 0:
		return c
	for x in range(1, i + 1):
		if y != l[i - x]:
			break
		c = c + 1
	return c

def palindrome(s):
	n = len(s)
	for i in range(int(n / 2)):
		if s[i] != s[n - 1 - i]:
			return (False, i)
	return (True,)

def positions(s):
	n = len(s)
	if n % 2 != 0:
		m = int((n - 1) / 2)
		t = palindrome(s)
		if t[0]:
			r = equi(m, s[m], s) + 1
			return (r, r)
		else:
			l = 0
			r = 0
			if s[m - 1] == s[m]:
				if palindrome(s[t[1]:n - 1 - t[1]])[0]:
					l = equi(t[1], s[n - 1 - t[1]], s) + 1
			if s[m] == s[m + 1]:
				s2 = s[n - 1::-1]
				t1 = palindrome(s2)[1]
				if palindrome(s2[t1:n - t1 - 1])[0]:
					r = equi(t1, s2[n - 1 - t1], s2) + 1
		return (l, r)
	else:
		m = int(n / 2)
		if palindrome(s)[0]:
			r = equi(m, s[m], s)
			return (r, r + 1)
		if s[m - 1] == s[m]:
			s1 = s[:m] + s[m + 1:]
			return positions(s1)
		else:
			s2 = s[:m - 1] + s[m:]
			s3 = s[:m] + s[m + 1:]
			return (positions(s2)[0], positions(s3)[1])
